CREATE OR REPLACE PROCEDURE FULL_PROC(INT4, NUMERIC(10,2))
RETURNS INT4
EXECUTE AS OWNER
LANGUAGE NZPLSQL AS
BEGIN_PROC
DECLARE
    v_cnt INT4 := 0;
    v_total NUMERIC(12,2) := 0;
    v_msg VARCHAR(200);
BEGIN
    IF p_dept IS NULL THEN
        RAISE EXCEPTION 'Department cannot be NULL';
    END IF;

    FOR rec IN SELECT SALARY FROM TESTDB..EMPLOYEES WHERE DEPARTMENT_ID = p_dept LOOP
        v_cnt := v_cnt + 1;
        v_total := v_total + rec;
    END LOOP;

    IF v_cnt = 0 THEN
        RAISE NOTICE 'No employees found';
        RETURN 0;
    ELSIF v_total > p_threshold THEN
        v_msg := 'Over threshold: ' || v_total;
        RAISE NOTICE '%', v_msg;
    ELSE
        RAISE DEBUG 'Under threshold';
    END IF;

    WHILE v_cnt > 0 LOOP
        v_cnt := v_cnt - 1;
        EXIT WHEN v_cnt < 0;
    END LOOP;

    RETURN v_cnt;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in FULL_PROC';
        ROLLBACK;
        RETURN -1;
END;
END_PROC;

